var DEPENDENCY_CLEANUP_BATCH_SIZE = 1e4;
function cleanupDependencies(schema, table, name4, side, options = {}) {
  const { after: after2, batchSize = DEPENDENCY_CLEANUP_BATCH_SIZE, noAdvisoryLocks, backend } = options;
  const queue = `'${name4.replace(SINGLE_QUOTE_REGEX2, "''")}'`;
  const cursor = after2 ? `AND ${side}_id > '${after2.replace(SINGLE_QUOTE_REGEX2, "''")}'::uuid` : "";
  const jobCursor = after2 ? `AND j.id > '${after2.replace(SINGLE_QUOTE_REGEX2, "''")}'::uuid` : "";
  const edge = `COALESCE((SELECT id FROM edge), '${MAX_UUID}'::uuid)`;
  const sql2 = `
    WITH edge AS (
      SELECT ${side}_id AS id
      FROM ${schema}.job_dependency
      WHERE ${side}_name = ${queue} ${cursor}
      ORDER BY ${side}_id
      OFFSET ${batchSize - 1}
      LIMIT 1
    ),
    removed AS (
      DELETE FROM ${schema}.job_dependency d
      WHERE ${side}_name = ${queue} ${cursor}
        AND ${walkBatchBound(`${side}_id`, `SELECT ${side}_id FROM ${schema}.job_dependency WHERE ${side}_name = ${queue} ${cursor}`, batchSize, backend)}
        AND NOT EXISTS (
          SELECT 1 FROM ${schema}.${table} j
          WHERE j.name = ${queue} ${jobCursor}
            AND j.id <= ${edge}
            AND j.id = d.${side}_id
        )
      RETURNING 1
    )
    SELECT
      (SELECT id FROM edge) AS "walkCursor",
      (SELECT count(*) FROM removed)::int AS deleted
  `;
  return locked(schema, sql2, table + "cleanupDependencies", noAdvisoryLocks);
}
