      provider: external_exports.enum(["gmail", "icloud", "cpanel", "other"]).optional().describe("Leave out to guess from the address (cPanel-style mail.<domain> otherwise)."),
      imap_host: external_exports.string().optional(),
      imap_port: external_exports.number().int().optional(),
      imap_tls: external_exports.boolean().optional().describe("Implicit TLS (port 993). false = STARTTLS."),
      smtp_host: external_exports.string().optional(),
      smtp_port: external_exports.number().int().optional(),
      smtp_tls: external_exports.boolean().optional().describe("Implicit TLS (port 465). false = STARTTLS (587)."),
