    if (q4.actorType) conds.push(eq(auditLog.actorType, q4.actorType));
    if (q4.allowed) conds.push(eq(auditLog.allowed, q4.allowed === "true"));
    if (q4.before) conds.push(lt(auditLog.id, q4.before));
